verify:
choices = {o: choices[n] for o, n in {'D': 'A', 'B': 'B', 'C': 'C', 'A': 'D'}.items()}; answer = {'A': 'D', 'B': 'B', 'C': 'C', 'D': 'A'}[answer]  # shuffled: original letters
def vals(s):
    s = s.replace(' only', '').replace(', and ', ' and ').replace(', ', ' and ')
    return {value(p) for p in s.split(' and ')}
x = symbols('x', real=True)
sol = set(solve(Eq(sqrt(x + 12), x), x))
assert sol == {4}
assert vals(choices[answer]) == sol
assert all(vals(choices[k]) != sol for k in choices if k != answer)
